// Question: does a dated document list and spacious, unassisted editor provide a useful minimal base?
const seed=()=>({"name": "Jordan Davis", "focuses": [{"id": 1, "title": "Position focus · 2026", "start": "2026-01-01", "end": "2026-12-31", "sections": []}, {"id": 2, "title": "Position focus · 2025", "start": "2025-01-01", "end": "2025-12-31", "sections": [{"kind": "Core objective", "objective": "Build and release a clearer next-step screen for one video devotional, using AI to help write code. Help viewers understand what they can do after watching without distracting them from the devotional itself. Work with Product to keep the language understandable for people who are unfamiliar with the platform.", "goals": ["Test the next-step screen with 20 viewers and record how many find the next step.", "Improve the screen based on feedback, then repeat the test with 20 viewers. Record which instructions people misinterpret and whether they can explain the next step in their own words. Summarise the findings and recommend which changes should be kept before the next release."]}, {"kind": "Core objective", "objective": "Improve the clarity of the devotional viewing experience.", "goals": ["Identify two points where viewers struggle to understand what to do next. Observe people using the current experience without coaching them, and capture the wording or screen elements that cause hesitation. Share a short summary with the team so that the proposed improvements address observed problems.", "Test revised instructions with five viewers and record their feedback."]}, {"kind": "Personal development", "objective": "Create an internal hub system for hosting prototypes. Give people in four departments a reliable place to find the latest version of each prototype, understand what feedback is being requested, and see who to contact. Keep the first version simple enough that each department can maintain its own entries without specialist help.", "goals": ["Collect and gather all hostable URLs from four different departments.", "Create a prototype hub and lay out the URLs for each of the four departments.", "Collect feedback on each department’s reception of the hosting platform. Ask participants to find a prototype that belongs to another department and explain whether its purpose and feedback request are clear. Record common difficulties, agree on the most useful improvements, and share the proposed changes with the department representatives."]}, {"kind": "Leadership initiative", "objective": "Facilitate 50% of the show-and-tell meetings for the current quarter.", "goals": ["Gather openers or fun topics for each of the available slots for ShareChat.", "Bookmark the show-and-tell facilitation guides in the browser. Review good-practice notes before each session.", "Encourage one team member who has not facilitated before to lead a session. Provide tips and a starter activity, and offer a practice session together. Help them prepare a simple running order, discuss how to invite quieter participants into the conversation, and agree on a backup plan if the discussion stalls. After the session, ask what felt comfortable and what support would help them facilitate again."]}]}]});
let s=seed(),page='list',selected=1,topic='Objectives',saved='';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const focus=()=>s.focuses.find(f=>f.id===selected);
const button=(label,action,cls='')=>`<button type="button" class="${cls}" data-action="${action}">${label}</button>`;
const date=x=>x?new Date(x+'T12:00:00').toLocaleDateString('en-NZ',{day:'numeric',month:'short',year:'numeric'}):'No date';
function state(){document.querySelector('#state').textContent=JSON.stringify(s,null,2)}
function go(p){page=p;saved='';render();window.scrollTo(0,0)}
function render(){document.querySelector('#app').innerHTML=`<aside><div class="brand"><span>♙</span> Lantern</div><nav>${[['list','◎','Position focuses'],['guide','▤','Guide'],['account','⚙','Account']].map(([p,i,t])=>button(i+'　'+t,'nav:'+p,(page===p||p==='list'&&page==='editor')?'active':'')).join('')}</nav><div class="aside-foot">Refine 3 · Document<br>Stacked reading layout</div></aside><main class="main"><div class="demo"><span>PROTOTYPE · Temporary memory · Refresh clears changes</span>${button('Reset demo','reset')}</div><div class="workspace">${page==='list'?list():page==='editor'?editor():page==='guide'?guide():account()}<details class="state"><summary>Prototype state</summary><pre id="state"></pre></details></div></main>`;state()}
function list(){return `<header><div><h1>Position focuses</h1><p class="muted">Your documents, organised by period.</p></div>${button('New position focus','new','primary')}</header><table class="focus-list"><thead><tr><th>Document</th><th>Period</th><th></th></tr></thead><tbody>${[...s.focuses].sort((a,b)=>b.start.localeCompare(a.start)).map(f=>`<tr><td>${button(esc(f.title),'open:'+f.id,'link')}</td><td class="period">${date(f.start)} – ${date(f.end)}</td><td>${button('Open','open:'+f.id)}</td></tr>`).join('')}</tbody></table><p class="muted" style="margin-top:24px">The current document starts empty. The 2025 document contains an illustrative example.</p>`}
function editor(){const f=focus();return `${button('← Position focuses','nav:list','link back')}<header><div><h1>${esc(f.title)}</h1><p class="muted">${date(f.start)} – ${date(f.end)}</p></div>${button('Edit title & dates','metadata')}</header>${f.sections.length?f.sections.map((x,i)=>`<section class="read-section"><div class="read-objective"><div class="row section-heading"><div class="section-label"><h2>Objective ${i+1}</h2>${x.kind!=='Core objective'?`<span class="badge">${esc(x.kind)}</span>`:''}</div><div class="section-tools">${button('Edit objective','editobjective:'+i,'link edit-action')}${button('Remove','remove:'+i,'link danger small-action')}</div></div><p class="read-text">${esc(x.objective)||'<span class="muted">No objective yet.</span>'}</p></div><div class="read-goals"><h3>SMART goals</h3>${x.goals.map((g,j)=>`<div class="read-goal"><span class="goal-number">${j+1}</span><p class="read-text">${esc(g)}</p><div>${button('Edit',`editgoal:${i}:${j}`,'link')}${button('Remove',`removegoal:${i}:${j}`,'link danger small-action')}</div></div>`).join('')||'<p class="muted">No goals yet.</p>'}${button('+ Add SMART goal','goal:'+i,'link')}</div></section>`).join(''):`<div class="empty-base"><h2>A blank position focus</h2><p class="muted">Add your first objective when you’re ready.</p>${button('Add objective','add:Core objective','primary')}</div>`}<div class="editor-actions"><div>${button('+ Add objective','add:Core objective')}</div><span class="save-status">${esc(saved)}</span></div>`}
function objectiveTypes(){return `<fieldset class="objective-types"><legend>Objective type</legend><p>Choose one. Every new objective starts as Normal.</p>${[['Core objective','Normal Objectives','Your main work objectives.'],['Personal development','Personal Development Objectives','Your personal growth and development.'],['Leadership initiative','Leadership Objectives','Your leadership contribution.']].map(([value,label,help],i)=>`<label class="type-choice"><input type="radio" name="objective-type" value="${value}" ${i===0?'checked':''}><span><strong>${label}</strong><small>${help}</small></span></label>`).join('')}</fieldset>`}
let editing=null;
function editText(kind,i,j,concern){editing={kind,i,j,concern};const value=kind==='objective'?focus().sections[i].objective:kind==='goal'?focus().sections[i].goals[j]:'';const label=kind==='goal'||kind==='newgoal'?'SMART goal':'Objective';modal(`<form id="edit-form"><h2>${kind.startsWith('new')?'Add':'Edit'} ${label.toLowerCase()}</h2>${kind==='newobjective'?objectiveTypes():''}<label for="edit-text">${label}</label><textarea id="edit-text" required autofocus>${esc(value)}</textarea><div class="dialog-actions">${button('Cancel','close')}<button type="submit" class="primary">Save changes</button></div></form>`)}
function editMetadata(){editing={kind:'metadata'};const f=focus();modal(`<form id="edit-form"><h2>Edit title & dates</h2><label for="edit-title">Document title</label><input id="edit-title" required value="${esc(f.title)}"><div class="metadata"><div><label for="edit-start">Period starts</label><input id="edit-start" type="date" value="${f.start}"></div><div><label for="edit-end">Period ends</label><input id="edit-end" type="date" value="${f.end}"></div></div><div class="dialog-actions">${button('Cancel','close')}<button type="submit" class="primary">Save changes</button></div></form>`)}
document.addEventListener('submit',e=>{if(e.target.id!=='edit-form')return;e.preventDefault();const f=focus(),x=editing;if(x.kind==='metadata'){f.title=document.querySelector('#edit-title').value;f.start=document.querySelector('#edit-start').value;f.end=document.querySelector('#edit-end').value}else{const value=document.querySelector('#edit-text').value.trim();if(!value)return; if(x.kind==='objective')f.sections[x.i].objective=value;if(x.kind==='goal')f.sections[x.i].goals[x.j]=value;if(x.kind==='newobjective')f.sections.push({kind:document.querySelector('[name=objective-type]:checked').value,objective:value,goals:[]});if(x.kind==='newgoal')f.sections[x.i].goals.push(value)}document.querySelector('#modal').close();saved='Saved in this session';render();toast(saved)});
let lessonStep=0;
const lessons={
Objectives:[
['Purpose','Describe the change you want','An objective explains the outcome your work should create, not just the activity you will do. It helps you decide which work matters.','Activity → Change','Hold more meetings.','Help new team members find the information they need to begin their work.','The stronger version describes a useful result for people.'],
['Define it','Name who benefits and how','Write one clear sentence: who will benefit, what will improve, and why that matters. Keep detailed targets for your goals.','People → Outcome → Purpose','Improve everything for everyone.','Help new team members find essential information so they can begin their work with confidence.','A defined audience and outcome make the objective easier to act on.'],
['Check it','Keep the objective focused','Choose an outcome you can influence and that supports your role. If it contains several unrelated outcomes, separate them.','One outcome → Focused work','Improve onboarding, organise events and rebuild the website.','Make essential onboarding information easier for new team members to find.','One outcome makes it easier to choose relevant SMART goals.']
],
'SMART goals':[
['S','Specific','Say exactly what you will do and what it applies to. A clear action turns the objective into work you can recognise.','Vague → Concrete','Make onboarding better.','Create a one-page checklist covering the five essential onboarding tasks.','The action and deliverable are explicit.'],
['M','Measurable','Describe evidence that will tell you whether the goal is met. Use a count, a quality check or a result you can observe.','Action → Evidence','Make the checklist easy to use.','Test the checklist with five new team members; at least four can find all five tasks without help.','You can check the outcome instead of guessing whether it is better.'],
['A','Achievable','Check the time, resources and support available. A useful goal stretches you without depending on an unrealistic promise.','Scope ↔ Capacity','Replace every department’s onboarding process this week.','Pilot one checklist with five new team members, using two agreed work sessions and help from the onboarding lead.','The smaller scope and agreed support make delivery plausible. Confirm that capacity together.'],
['R','Relevant','Show how the goal contributes to your objective. A measurable activity can still be the wrong work.','Goal → Objective','Redesign the team’s social-event poster.','Test whether new team members can find their onboarding tasks using the checklist.','This directly supports the objective of finding essential onboarding information.'],
['T','Time-bound','Set a clear completion date or period. Agree timing that fits the work rather than adding an arbitrary deadline.','Start ───── Finish','Test the checklist soon.','By 30 June, test the checklist with five new team members and record the results.','A clear finish point lets you plan the work and review progress.']
]};
function previousGuide(){const tabs=`<div class="lesson-tabs" aria-label="Guide topics">${['Objectives','SMART goals','Example'].map(t=>button(t,'topic:'+t,topic===t?'primary':'')).join('')}</div>`;if(topic==='Example')return `<header><div><h1>A simple position focus</h1></div></header>${tabs}<section class="read-section"><div class="read-objective"><div class="section-label"><h2>Objective 1</h2></div><p class="read-text">Help new team members find essential information so they can begin their work with confidence.</p></div><div class="read-goals"><h3>SMART goals</h3><div class="read-goal"><span class="goal-number">1</span><p class="read-text">By 31 May, publish a one-page checklist covering the five essential onboarding tasks, checked by the onboarding lead.</p></div><div class="read-goal"><span class="goal-number">2</span><p class="read-text">By 30 June, test the checklist with five new team members; at least four can find all five tasks without help.</p></div></div></section><div class="lesson-footer">${button('← Review SMART goals','topic:SMART goals')}${button('Go to my position focuses','nav:list','primary')}</div>`;
const steps=lessons[topic],x=steps[lessonStep];return `<header><div><h1>${topic==='Objectives'?'What makes a useful objective?':'Build a SMART goal'}</h1><p class="muted">${topic==='Objectives'?'Understand the purpose, write it clearly, then check the focus.':'One quality at a time. Apply all five to the finished goal.'}</p></div></header>${tabs}<div class="step-nav" aria-label="Lesson steps">${steps.map((v,i)=>`<button type="button" data-action="step:${i}" aria-current="${i===lessonStep?'step':'false'}"><span>${topic==='Objectives'?i+1:v[0]}</span>${topic==='Objectives'?v[0]:v[1]}</button>`).join('')}</div><section class="lesson-card"><div class="lesson-kicker">${topic} · ${lessonStep+1} of ${steps.length}</div><h2>${x[1]}</h2><p class="lesson-intro">${x[2]}</p><div class="lesson-diagram" aria-label="${x[3]}">${x[3].split(/ → | ↔ | ───── /).map((v,i)=>`${i?'<span aria-hidden="true">→</span>':''}<strong>${v}</strong>`).join('')}</div><div class="example-pair"><div><span class="example-label">Needs work</span><p>${x[4]}</p></div><div><span class="example-label">Stronger example</span><p>${x[5]}</p></div></div><p class="why"><strong>Why it works</strong> ${x[6]}</p></section><div class="lesson-footer">${lessonStep?button('← Previous','step:'+(lessonStep-1)): '<span></span>'}${lessonStep<steps.length-1?button('Next →','step:'+(lessonStep+1),'primary'):button(topic==='Objectives'?'Continue to SMART goals →':'See the full example →','topic:'+(topic==='Objectives'?'SMART goals':'Example'),'primary')}</div>`}

function guideNavigation(){return `<div class="guide-navigation"><div class="area-heading">Guide topics</div><div class="topic-group">${['Objectives','SMART goals','Example'].map(t=>`<button type="button" data-action="topic:${t}" aria-pressed="${topic===t}" class="${topic===t?'selected':''}">${t}</button>${topic===t&&topic!=='Example'&&3===4?stepNavigation():''}`).join('')}</div>${3===3&&topic!=='Example'?stepNavigation():''}</div>`}
function stepNavigation(){return `<div class="lesson-steps" aria-label="Steps within ${topic}">${lessons[topic].map((v,i)=>`<button type="button" data-action="step:${i}" aria-current="${i===lessonStep?'step':'false'}"><span>${topic==='Objectives'?i+1:v[0]}</span>${topic==='Objectives'?v[0]:v[1]}</button>`).join('')}</div>`}
function guide(){if(topic==='Example'){const old=previousGuide();return old.replace(/<div class="lesson-tabs"[\s\S]*?<\/div>/,guideNavigation())}const steps=lessons[topic],x=steps[lessonStep];const weak=topic==='Objectives'?['Activity without an outcome','Audience and outcome unclear','Too many unrelated outcomes'][lessonStep]:['Action is vague','Success cannot be checked','Scope exceeds likely capacity','Does not support this objective','No completion date'][lessonStep];const strong=topic==='Objectives'?['A useful outcome for people','A defined audience and benefit','One focused outcome'][lessonStep]:['A concrete action and deliverable','An observable success measure','A manageable pilot with support','Directly supports the objective','A clear completion date'][lessonStep];return `<header><h1>${topic==='Objectives'?'What makes a useful objective?':'Build a SMART goal'}</h1></header><div class="guide-layout">${guideNavigation()}<div class="lesson-body"><section class="lesson-card"><h2>${x[1]}</h2><p class="lesson-intro">${x[2]}</p><div class="comparison-heading">Compare the examples</div><div class="example-pair"><div class="weak-example"><div class="example-title"><span class="example-icon" aria-hidden="true">×</span><h3>Needs work</h3></div><p>${x[4]}</p><div class="example-reason">${weak}</div></div><div class="strong-example"><div class="example-title"><span class="example-icon" aria-hidden="true">✓</span><h3>Stronger example</h3></div><p>${x[5]}</p><div class="example-reason">${strong}</div></div></div><section class="explanation"><h3><span aria-hidden="true">✦</span> Why it works</h3><p>${x[6]}</p></section></section><div class="lesson-footer">${lessonStep?button('← Previous','step:'+(lessonStep-1)):'<span></span>'}${lessonStep<steps.length-1?button('Next →','step:'+(lessonStep+1),'primary'):button(topic==='Objectives'?'Continue to SMART goals →':'See the full example →','topic:'+(topic==='Objectives'?'SMART goals':'Example'),'primary')}</div></div></div>`}

function account(){return `<header><div><h1>Account</h1><p class="muted">Your profile information.</p></div></header><section class="read-section profile-card"><div class="row"><h2>Profile</h2>${button('Edit name','editprofile','link edit-action')}</div><dl><div><dt>Display name</dt><dd>${esc(s.name)}</dd></div><div><dt>Email</dt><dd>jordan@example.test</dd></div></dl><p class="muted profile-note">This demo uses a fictional account.</p></section>`}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='editprofile')modal(`<form id="profile-form"><h2>Edit display name</h2><label for="profile-name">Display name</label><input id="profile-name" value="${esc(s.name)}" required><div class="dialog-actions">${button('Cancel','close')}<button type="submit" class="primary">Save changes</button></div></form>`);if(a?.startsWith('step:')){lessonStep=Number(a.split(':')[1]);render();window.scrollTo(0,0)}});
document.addEventListener('submit',e=>{if(e.target.id!=='profile-form')return;e.preventDefault();const name=document.querySelector('#profile-name').value.trim();if(!name)return;s.name=name;document.querySelector('#modal').close();render();toast('Profile saved in this session')});
function modal(html){document.querySelector('#modal').innerHTML=html;if(!document.querySelector('#modal').open)document.querySelector('#modal').showModal()}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.timer);window.timer=setTimeout(()=>el.style.display='none',2500)}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field)focus()[el.dataset.field]=el.value;if(el.hasAttribute('data-objective'))focus().sections[+el.dataset.section].objective=el.value;if(el.hasAttribute('data-goal'))focus().sections[+el.dataset.section].goals[+el.dataset.goal]=el.value;if(el.hasAttribute('data-name'))s.name=el.value;saved='Unsaved changes';const status=document.querySelector('#save-status');if(status)status.textContent=saved;state()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const [a,v,j]=b.dataset.action.split(':');if(a==='nav')go(v);if(a==='open'){selected=+v;go('editor')}if(a==='new'){const id=Date.now();s.focuses.unshift({id,title:'Untitled position focus',start:'',end:'',sections:[]});selected=id;go('editor')}if(a==='add'){document.querySelector('#modal').close();editText('newobjective',null,null,v)}if(a==='goal')editText('newgoal',+v);if(a==='editobjective')editText('objective',+v);if(a==='editgoal')editText('goal',+v,+j);if(a==='metadata')editMetadata();if(a==='remove'||a==='removegoal')modal(`<h2>Remove this ${a==='remove'?'objective and its goals':'goal'}?</h2><p>This changes only your temporary document.</p>${button('Remove',`confirm${a}:${v}${j===undefined?'':':'+j}`,'danger')} ${button('Cancel','close')}`);if(a==='confirmremove'){focus().sections.splice(+v,1);document.querySelector('#modal').close();render()}if(a==='confirmremovegoal'){focus().sections[+v].goals.splice(+j,1);document.querySelector('#modal').close();render()}if(a==='optional')modal(`<h2>Add an optional focus</h2><p>The same objective and SMART goals, with a label for its purpose.</p><div class="stack">${button('Personal development','add:Personal development')}${button('Leadership initiative','add:Leadership initiative')}</div><p style="margin-top:24px">${button('Cancel','close')}</p>`);if(a==='close')document.querySelector('#modal').close();if(a==='save'){saved='Saved in this session';render();toast(saved)}if(a==='savename')toast('Name saved in this session');if(a==='topic'){topic=v;lessonStep=0;render();window.scrollTo(0,0)}if(a==='reset'){s=seed();selected=1;go('list');toast('Demo reset')}});
render();
